import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.HashSet;
import java.util.HashMap;
import java.util.Map;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single actor, either an animal or plant.
 *
 *
 * @version 27.02.22
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();
    private static final int MAX_ALTITUDE = 5;
    // The depth and width of the field.
    private int depth, width;
    // Storage for the animals, plants, weather and altitude.
    private Object[][] animalField;
    private Object[][] plantField;
    private Map<String, double[][]> weatherField;
    private int[][] altitudeField;
    private  int waterLevel;
    private static final int maxWaterLevel = 3;
    private static final int minWaterLevel = 1;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        animalField = new Object[depth][width];
        plantField = new Object[depth][width];
        weatherField = createWeatherFieldMap(depth, width);
        altitudeField = new int[depth][width];
        waterLevel = maxWaterLevel;
    }

    /**
     * Create a Map with a key of the weather condition attribute name
     * and a value of weather attribute.
     * @param depth The depth of the field.
     * @param width The width of the field.
     * @return The weather field Map.
     */
    private Map<String, double[][]> createWeatherFieldMap(int depth, int width)
    {
        Map<String, double[][]> mapTemp = new HashMap<>();
        WeatherCond weatherTemp = WeatherCond.Sunny;
        for (String weatherAttribute : weatherTemp.getWeatherAttributesMap().keySet()) {
            mapTemp.put(weatherAttribute, new double[depth][width]);
        }
        return mapTemp;
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                animalField[row][col] = null;
                plantField[row][col] = null;
                for (String weatherAttribute : weatherField.keySet()) {
                    weatherField.get(weatherAttribute)[row][col] = 0;
                }
                altitudeField[row][col] = MAX_ALTITUDE;
            }
        }
        generateTerrain();
    }

    /**
     * Clear the given location.
     * The type of actor is specified to clear the correct actor field.
     * @param actor The actor in the location being cleared.
     * @param location The location to clear.
     */
    public void clear(Actor actor, Location location)
    {
        if (actor instanceof Animal){
            animalField[location.getRow()][location.getCol()] = null;
        }
        else if (actor instanceof Plant){
            plantField[location.getRow()][location.getCol()] = null;
        }
    }

    /**
     * Place an actor at the given location.
     * If there is already an actor at the location it will
     * be lost.
     * @param actor The actor to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object actor, int row, int col)
    {
        place(actor, new Location(row, col));
    }

    /**
     * Place an actor at the given location.
     * If there is already an actor at the location it will
     * be lost.
     * @param actor The actor to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object actor, Location location)
    {
        if (actor instanceof Animal) {
            animalField[location.getRow()][location.getCol()] = actor;
        }
        else if (actor instanceof Plant) {
            plantField[location.getRow()][location.getCol()] = actor;
        }
    }

    /**
     * Return the actor at the given location, if any.
     * @param location Where in the field.
     * @return The actor at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the actor at the given location, if any.
     * Animals are prioritised over Plants, and are returned if both
     * are present in that location.
     * @param row The desired row.
     * @param col The desired column.
     * @return The actor at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        if (animalField[row][col] != null) {
            return animalField[row][col];
        }
        return plantField[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param actor The actor finding free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Actor actor, Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);

        for(Location next : adjacent) {

            if ((getObjectAt(next) == null || (actor instanceof Animal && getObjectAt(next) instanceof Plant))
                    && actor.canAccessLocation(next)) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param actor The actor finding a free adjacent location.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Actor actor, Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(actor, location);
        if(!free.isEmpty()) {
            return free.get(0);
        }
        return null;
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }

    /**
     * Set the values of each weather attributes field uniformly
     * distributed around a specified average.
     * @param weather The weather condition.
     */
    public void setWeatherField(WeatherCond weather) 
    {
        for (String weatherAttribute : weatherField.keySet()) {
            double avgWeather = weather.getWeatherAttributesMap().get(weatherAttribute);
            for(int row = 0; row < depth; row++) {
                for(int col = 0; col < width; col++) {
                    weatherField.get(weatherAttribute)[row][col] = avgWeather + (rand.nextDouble() - 0.5) * 2 / 5;
                }
            }
        }

        if(weather.getDampness() > 0.7 && waterLevel < maxWaterLevel){
            waterLevel += 1;
        }

        else if (waterLevel> minWaterLevel){
            if(weather.getBrightness() > 0.9 && waterLevel > minWaterLevel + 1){
                waterLevel -=2;
            }
            else {
                waterLevel -= 1;
            }
        }
    }

    /**
     * Returns the weather attribute value at a specified location.
     * @param weatherAttribute The String name of the weather attribute.
     * @param loc The location.
     * @return The weather attribute value at the specified location.
     */
    public double getWeatherAttributeValueAt(String weatherAttribute, Location loc)
    {
        return weatherField.get(weatherAttribute)[loc.getRow()][loc.getCol()];
    }

    /**
     * Returns whether or not the location with the specified row and column
     * is under water.
     * @param row The desired row.
     * @param col The desired column.
     * @return Whether or not the location is under water.
     */
    public boolean isUnderWater(int row, int col)
    {
        return altitudeField[row][col] <= waterLevel;
    }

    /**
     * Randomly generates altitude numbers in the altitude field.
     */
    public void generateTerrain()
    {
        Location centre = new Location(rand.nextInt(depth), rand.nextInt(width));
        boolean horizontal = rand.nextBoolean();
        if (horizontal) {
            for (int z = 0; z < width; z++) {
                altitudeField[centre.getRow()][z] = 0;
            }
            int stop = 0;
            int x = 0;
            while (stop < depth / 6) {
                x++;
                Location topOrLeft = new Location(centre.getRow() - x, centre.getCol() - x);
                stop += incrementAltitude(topOrLeft.getRow(), topOrLeft.getCol(), topOrLeft.getRow() + 1, topOrLeft.getCol() + 1);
                Location bottomOrRight = new Location(centre.getRow() + x, centre.getCol() + x);
                stop += incrementAltitude(bottomOrRight.getRow(), bottomOrRight.getCol(), bottomOrRight.getRow() - 1, bottomOrRight.getCol() - 1);
                for (int z = 0; z < width; z++) {
                    stop += incrementAltitude(topOrLeft.getRow(), z, topOrLeft.getRow() + 1, z);
                    stop += incrementAltitude(bottomOrRight.getRow(), z, bottomOrRight.getRow() - 1, z);
                }
            }
        }
        else {
            for (int z = 0; z < depth; z++) {
                altitudeField[z][centre.getCol()] = 0;
            }
            int stop = 0;
            int x = 0;
            while (stop < width / 9) {
                x++;
                Location topOrLeft = new Location(centre.getRow() - x, centre.getCol() - x);
                stop += incrementAltitude(topOrLeft.getRow(), topOrLeft.getCol(), topOrLeft.getRow() + 1, topOrLeft.getCol() + 1);
                Location bottomOrRight = new Location(centre.getRow() + x, centre.getCol() + x);
                stop += incrementAltitude(bottomOrRight.getRow(), bottomOrRight.getCol(), bottomOrRight.getRow() - 1, bottomOrRight.getCol() - 1);
                for (int z = 0; z < width; z++) {
                    stop += incrementAltitude(z, topOrLeft.getCol(), z, topOrLeft.getCol() + 1);
                    stop += incrementAltitude(z, bottomOrRight.getCol(), z, bottomOrRight.getCol() - 1);
                }
            }
        }
    }

    private int incrementAltitude(int row, int col, int adjRow, int adjCol)
        {
        if (row < depth && col < width && adjRow < depth && adjCol < width && row > 0 && col > 0 && adjRow > 0 && adjCol > 0) {
            int newAltitude;
            if (rand.nextInt(depth * width / 1000) == 0) {
                newAltitude = altitudeField[adjRow][adjCol] + 1;
            }
            else {
                newAltitude = altitudeField[adjRow][adjCol];
            }
            altitudeField[row][col] = Math.min(Math.max(newAltitude, 0), MAX_ALTITUDE);
            if (altitudeField[row][col] == MAX_ALTITUDE) {
                return 1;
            }
        }
        return 0;
    }
}

import java.util.List;
import java.util.HashSet;
import java.util.Map;
import java.util.Random;
import java.util.Set;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 27.02.22
 */
public abstract class Animal extends Actor
{
    protected int foodLevel;
    protected boolean female;
    protected boolean nocturnal;

    /**
     * Create a new animal at location in field with time as well.
     * With a set that will add any disease that it catches
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param time The time in the simulation
     */
    public Animal(Time time, Field field, Location location)
    {
        super(time, field, location);

    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * Checks if the time of day matches if the animal is nocturnal or not,
     * then attempts to find food and move.
     * @param newAnimals A list to receive newly born animals.
     * @param weather The weather condition of the simulation.
     */
    public void act(List<Actor> newAnimals, WeatherCond weather)
    {
        super.act(newAnimals,weather);
        incrementHunger();
        if(isAlive()&&(getTime().isDay() != nocturnal)) {
            giveBirth(newAnimals);            
            // Move towards a source of food if found.
            Location newLocation = null;
            if (getField().getWeatherAttributeValueAt("visibility", getLocation()) > 0.4){
                newLocation = findFood();
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(this, getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Checks if the animal is female and looks for a mate
     * @param newAnimals The List of new animals that have been born to add to the simulator List of actors
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        if (female&&findMate()) {
            super.giveBirth(newAnimals);
        }
    }

    /**
     * Searches for a mate to breed with.
     * Searches first for an adjacent animal of the same dynamic type,
     * then if that animal is male.
     * @return true if a mate is found.
     */
    protected boolean findMate()
    {
        Field field = getField();
        for(Location where : field.adjacentLocations(getLocation())) {
            Object actor = field.getObjectAt(where);
            if (actor instanceof Animal) {
                Animal animal = (Animal) actor;
                if (animal.getClass() == getClass() && !animal.female){
                    giveDiseases(animal);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Transfer diseases between mates. Snapshot own diseases first to avoid
     * re-sending diseases that were just received from the mate.
     * @param mate The male mate that the female breeds with.
     */
    protected void giveDiseases(Animal mate)
    {
        Set<Disease> ownDiseasesSnapshot = new HashSet<>(setDiseases);
        for (Disease disease: mate.getActorDiseaseSet()){
            if (disease.isSpreadByBirth()){
                contractDisease(disease);
            }
        }
        for (Disease disease: ownDiseasesSnapshot){
            if (disease.isSpreadByBirth()){
                mate.contractDisease(disease);
            }
        }
    }

    /**
     * Look for prey adjacent to the current location.
     * Only the first live prey is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Field field = getField();
        for(Location where : field.adjacentLocations(getLocation())) {
            if (canAccessLocation(where)) {
                Object actor = field.getObjectAt(where);
                if (actor instanceof Actor) {
                    Actor prey = (Actor) actor;
                    Integer foodValue = getPreyFoodValuesMap().get(prey.getClass());
                    if(foodValue != null && prey.isAlive()) {
                        for (Disease disease: prey.getActorDiseaseSet()){
                            if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getClass())){
                                contractDisease(disease);
                            }
                        }
                        prey.setDead();
                        foodLevel = Math.min(foodLevel + foodValue, getMaxFood());
                        return where;
                    }
                }
            }
        }
        return null;
    }

    /**
     * Returns how many animals are produced during birth.
     * Uses the abstract breeding parameters defined by each subclass.
     * @return The number of births (may be zero).
     */
    public int breed()
    {
        Random rand = Randomizer.getRandom();
        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            return rand.nextInt(getMaxLitterSize()) + 1;
        }
        return 0;
    }

    private boolean canBreed()
    {
        return age >= getBreedingAge();
    }

    abstract protected int getBreedingAge();
    abstract protected double getBreedingProbability();
    abstract protected int getMaxLitterSize();

    abstract protected Animal spawnOffspring(Location loc, Set<Disease> parentDiseases);
    abstract protected Animal spawnRandom(Location loc);

    /**
     * Returns the Map of the prey of the animal and how much food they provide it
     * @return The Map of the prey of the animal and how much food they provide it
     */
    abstract protected Map<Class<? extends Actor>, Integer> getPreyFoodValuesMap();

    /**
     * Returns the max food value that the animal can have
     * @return The max food value that the animal can have
     */
    abstract protected int getMaxFood();
}

import java.util.List;
import java.util.Random;
import java.util.Set;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 27.02.22
 */
public abstract class Plant extends Actor
{

    private double waterLevel;
    private double sunLightLevel;
    private static final double MAX_WATER_LEVEL = 2.5;
    private static final double WATER_DECAY = 0.5;
    private static final double SUNLIGHT_DECAY = 0.25;

    /**
     * Create a new plant at location in field with time as well.
     * With a set that will add any disease that it catches
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param time The time in the simulation
     */
    public Plant(Time time, Field field, Location location)
    {
        super(time, field, location);
        waterLevel = 1.5;
        sunLightLevel = 1.5;
    }

    /**
     * Make this plant act - that is: make it do
     * whatever it wants/needs to do.
     * Checks weather and updates water and sunlight levels accordingly.
     * @param newPlants A list to receive newly born plants.
     * @param weather The weather condition of the simulation.
     */
    public void act(List<Actor> newPlants, WeatherCond weather)
    {
        super.act(newPlants, weather);
        if (isAlive()){
            waterLevel -= WATER_DECAY;
            sunLightLevel -= SUNLIGHT_DECAY;
            sunLightLevel += getField().getWeatherAttributeValueAt("brightness", getLocation());
            double dampness = getField().getWeatherAttributeValueAt("dampness", getLocation());
            waterLevel = Math.min(waterLevel + dampness, MAX_WATER_LEVEL);
            if (waterLevel < 0 || sunLightLevel <= 0){
                setDead();
            }
            else {
                giveBirth(newPlants);            
            }
        }
    }

    /**
     * Returns how many plants are produced during birth.
     * Uses the abstract breeding parameters defined by each subclass.
     * @return The number of births (may be zero).
     */
    public int breed()
    {
        Random rand = Randomizer.getRandom();
        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            return rand.nextInt(getMaxLitterSize()) + 1;
        }
        return 0;
    }

    private boolean canBreed()
    {
        return age >= getBreedingAge();
    }

    abstract protected int getBreedingAge();
    abstract protected double getBreedingProbability();
    abstract protected int getMaxLitterSize();

    abstract protected Plant spawnOffspring(Location loc, Set<Disease> parentDiseases);
    abstract protected Plant spawnRandom(Location loc);
}

