    public WeatherCond nextCondition()
    {
        List<WeatherCond> tempList = new ArrayList<>();
        switch(this) {
            case Sunny:
                tempList.add(Cloudy);
                tempList.add(Windy);
                break;
            case Rain:
                tempList.add(Storm);
                tempList.add(Cloudy);
                break;
            default:
                if(timeOfDay.isDay()) { tempList.add(Sunny); }
                tempList.add(Fog);
                tempList.add(Rain);
                break;
